groups = [('A','Ý tưởng và tính mới'),('B','Kỹ thuật ACT/ML'),('C','Dữ liệu'),('D','Mô phỏng và sim-to-real'),('E','Triển khai tại nhà máy')]
qa = [
('A01','Các bạn giải quyết bài toán gì, trong một phút?','Hiểu mục tiêu và giới hạn phạm vi.',
'Nhóm nhắm tới gắp và đặt linh kiện nhỏ vào khay hoặc khuôn, với mục tiêu giảm công cấu hình khi có các biến thể liên quan. Bài thử hiện tại là Panda trong MuJoCo, đặt ba chốt vào ba lỗ. Nhánh học mới dùng ảnh nhiều camera, trạng thái bảy khớp và độ mở kẹp để dự đoán chuỗi joint. Nhóm đã có mô phỏng, evaluator và pipeline dữ liệu; thành công closed-loop của joint policy và lợi ích trên cell DENSO vẫn phải đo. Vì vậy đây là prototype nghiên cứu có lộ trình pilot, chưa phải sản phẩm đã nghiệm thu.',
'[[J:configs/mujoco/panda_three_pegs.json:1]] [[J:src/models/mcr_act.py:94]] [[H::5754]]; S2/12/42.',
'“Đã tự động hóa công đoạn DENSO với độ chính xác cao.”','Công đoạn thật nào, mã linh kiện nào và tiêu chí nghiệm thu là gì?'),
('A02','ACT có sẵn, vậy tính mới của nhóm ở đâu?','Phân biệt đóng góp triển khai với phát minh học thuật.',
'ACT và MCR là phương pháp của các tác giả, nhóm không nhận là thuật toán mới. Phần nhóm có source là adapter dữ liệu CFG5, căn timestamp, mask camera thiếu, camera identity embedding, cache feature MCR, quản lý contract và evaluator cho task chốt. Giá trị đề xuất là ghép chúng thành một quy trình có thể kiểm tra và thích nghi cho công đoạn cụ thể. Tuy nhiên, tổ hợp đó có tốt hơn baseline hoặc giảm giờ công hay không thì chưa có phép so sánh của nhóm, nên tính mới ứng dụng và hiệu quả vẫn cần chứng minh bằng pilot.',
'[[J:src/data/cfg5_masked.py:205]] [[J:src/models/rh20t_act.py:34]] [[J:src/models/mcr_act.py:44]]; nguồn ACT/MCR trong04.',
'“Nhóm sáng chế ACT/CVAE hoặc một foundation model mới.”','Ablation nào chứng minh adapter của nhóm tạo thêm giá trị?'),
('A03','Dự án chỉ có một tay máy, tại sao thuộc Humanoid & Robot?','Mức phù hợp với chủ đề, tránh phóng đại humanoid.',
'Nhóm làm nhánh robot manipulation trong chủ đề Humanoid & Robot, không xây dựng một humanoid toàn thân. Panda là nền thử để nghiên cứu quy trình học thao tác và đánh giá trước khi chuyển sang thiết bị được chốt với xưởng. Chủ đề công khai có các hướng học skill từ dữ liệu và tự động hóa linh hoạt, nên bài toán có điểm phù hợp. Nhưng nhóm phải nói rõ phạm vi một tay và chưa giải quyết cân bằng, đi bộ hay phối hợp toàn thân. Nếu BTC yêu cầu một embodiment cụ thể, nhóm sẽ cần điều chỉnh phạm vi và xác nhận với mentor.',
'S12; [[J:src/simulation/panda_controller.py:34]]; [Technology Challenges](https://densohackathon.vn/theme), truy cập17/10/2026.',
'“Panda là humanoid” hoặc “chuyển sang mọi humanoid đều giống nhau”.','Dự án đăng ký H1 hay H3, deliverable cụ thể là gì?'),
('A04','Tại sao chọn chốt và khuôn thay vì linh kiện thật?','Hiểu surrogate task và external validity.',
'Chốt và lỗ có hình học rõ nên nhóm định nghĩa được thế nào là cắm đúng, chạm đáy, đã nhả và đứng ổn định. Task này giúp kiểm các khối simulation, controller và evaluator mà không cần ngay dữ liệu vật liệu thật. Nó chưa đại diện đầy đủ cho linh kiện dễ vỡ hoặc bề mặt phản xạ của DENSO. Nhóm cần lấy bản vẽ, gripper, dung sai và điều kiện chất lượng của cell đích, rồi xây bài thử tương ứng. Kết quả trên chốt chỉ được báo trong phạm vi chốt, không được suy thành nghiệm thu linh kiện nhà máy.',
'[[J:configs/mujoco/panda_three_pegs.json:1]] [[J:src/simulation/panda_evaluator.py:6]]; S13.',
'“Chốt nhỏ hơn nên chắc chắn khó hơn mọi linh kiện thật.”','Sự khác nhau nào giữa chốt mô phỏng và linh kiện dễ vỡ là quan trọng nhất?'),
('A05','Tại sao cần tới tám camera?','Lựa chọn thiết kế có đo chi phí/lợi ích hay chỉ sao chép.',
'Tám slot hiện xuất phát từ cấu hình camera CFG5 và rig mô phỏng mà nhóm muốn đối chiếu, gồm sáu camera ngoài và hai in-hand. Nhiều góc nhìn có thể giảm che khuất, nhưng đó là lý do thiết kế chứ chưa chứng minh tám camera là tối ưu. Nhánh mới còn xử lý camera thiếu bằng attention mask và camera dropout. Trước triển khai thật, nhóm cần ablation một, hai, ba và tám view trên cùng protocol, đồng thời đo chi phí, calibration, đồng bộ và latency. Nếu ít camera vẫn đạt tiêu chí thì nên giảm rig.',
'[[J:configs/data/cfg5_all8.json:6]] [[J:src/models/mcr_act.py:100]]; S18.',
'“Tám camera luôn chính xác hơn” hoặc “đã có tám camera thật”.','Camera nào đóng góp nhiều nhất và camera mất thì policy có chạy được không?'),
('A06','Tới hôm nay các bạn thực sự đã làm được gì?','Sự trung thực và mức hoàn thiện.',
'Nhóm có source môi trường Panda, controller scripted và evaluator; báo cáo controller cũ đạt ba trên ba seed. ACT TCP trước đây đã train và có thử transfer mười episode nhưng không thành công task nào. Sau đó nhóm chuyển sang joint và MCR, cache CFG5 mới đã hoàn tất theo log. Ghi chép ngày16/10 là người dùng báo đang ở epoch25 và yêu cầu tiếp tới100; hiện chưa có history hoặc rollout joint mới để kiểm độc lập. Vì vậy nhóm chưa công bố success rate của policy mới, robot thật hay few-shot như kết quả đã đạt.',
'[[L:outputs/controller_evaluation/summary.json:1]] [[R:epoch5_transfer_probe_14120/report.json:1]] [[H::5754]]; cache log trong00.',
'“Mọi phần đã chạy end-to-end” hoặc “ACT đạt100%”.','Vậy video demo đang chiếu là controller hay policy, checkpoint nào?'),

('B01','Action chunking giải quyết điều gì, K=20 nghĩa là gì?','Hiểu compounding error và deployment.',
'ACT dự đoán một đoạn hành động có liên quan từ observation hiện tại, thay vì chỉ một bước. Điều này giúp học sự nhất quán của chuyển động và giảm khó khăn ghép nhiều quyết định nhỏ, nhưng không xóa distribution shift. K20 của nhánh này là hai mươi bước trên grid10Hz, tương ứng hai giây nhãn tương lai. Khi triển khai có thể thực hiện cả đoạn, một phần đoạn hoặc hỏi lại mỗi tick rồi ensemble. Những cách đó có độ phản ứng và chi phí khác nhau; nhánh joint mới chưa có executor rollout được xác minh nên nhóm chưa chốt tần số truy vấn thực tế.',
'[[J:configs/act/rh20t_all8.json:1]] [[J:src/data/act_dataset.py:115]];02 mục1/6.',
'“K20 nghĩa là20task” hoặc “chunking bảo đảm không tích lũy lỗi”.','Nếu vật dịch chuyển giữa chunk hai giây thì xử lý thế nào?'),
('B02','CVAE và latent z có vai trò gì?','Hiểu cơ chế train, không đọc thuộc tên mô hình.',
'CVAE dùng biến ẩn để mô hình hóa khác biệt giữa các chunk hợp lý cho một observation, chẳng hạn cách tiếp cận hoặc nhịp chuyển động. Trong source này, posterior encoder nhận state và action chunk nhãn, tạo mu và log variance32chiều, rồi lấy mẫu z bằng reparameterization. Token latent được kết hợp với ảnh và proprio để dự đoán chunk. KL kéo posterior gần prior. Khi inference không có tương lai thật để đưa vào posterior, model dùng z bằng0. Nhóm không khẳng định mỗi chiều latent có ý nghĩa thao tác dễ diễn giải hoặc đã đo được lợi ích CVAE trên task của mình.',
'[[J:src/models/mcr_act.py:113]] [[J:third_party/rh20t_act/models/detr/models/detr_vae.py:65]].',
'“z là nhãn task có sẵn” hoặc “inference lấy z từ action thật”.','Nếu bỏ KL hoặc dùng latent ngẫu nhiên thì có thể xảy ra gì?'),
('B03','Loss gồm gì và vì sao KL weight bằng10?','Hiểu mục tiêu tối ưu, normalization và căn cứ hyperparameter.',
'Loss là masked L1 giữa chuỗi action dự đoán và nhãn đã chuẩn hóa, cộng10lần KL của posterior Gaussian với prior chuẩn trong config nền. L1 chỉ chia cho số phần tử nhãn thật, bỏ padding. KL cộng theo chiều latent rồi trung bình batch. Hệ số10 kế thừa baseline RH20T ACT; chưa có sweep của nhóm nên không gọi là tối ưu. L1 normalized cũng không phải millimet hay độ. Muốn đánh giá robot phải denormalize, đo lỗi joint và kẹp riêng, rồi đo task success closed-loop.',
'[[J:src/models/rh20t_act.py:54]] [[J:src/models/mcr_act.py:140]] [[J:configs/act/rh20t_all8.json:1]].',
'“Loss0,1 nghĩa là sai0,1mm”, hoặc “10đã được chứng minh tối ưu”.','Nếu KL rất nhỏ thì có chắc CVAE hoạt động tốt không?'),
('B04','Validation loss thấp có giống inference robot không?','Phát hiện target leakage về chế độ posterior.',
'Không hoàn toàn giống. Validation hiện gọi model với actions nhãn nên CVAE vẫn lấy posterior, dù đã eval mode và không cập nhật trọng số. Eval chủ yếu tắt dropout và điều khiển các layer theo mode, không tự bỏ target. Inference triển khai không truyền actions và dùng latent0. Do đó posterior reconstruction thấp là kiểm tra hữu ích nhưng chưa đo đúng chất lượng prior prediction, càng chưa đo rollout. Nhóm cần báo riêng posterior loss, prior z0 error trên held-out và closed-loop success; số E58 cũ không được gán cho joint model mới.',
'[[J:src/training/pretrain.py:283]] [[J:src/models/mcr_act.py:113]] [[J:src/models/mcr_act.py:125]].',
'“Đã model.eval nên chắc chắn z=0 và tương đương robot chạy.”','Trong hàm forward, điều kiện chọn posterior nằm ở dòng nào?'),
('B05','Tám camera đi qua model như thế nào?','Hiểu backbone, tokens và mask.',
'Ảnh từng view đi qua cùng một MCR ResNet50, không phải tám mạng độc lập. Sau resize/crop224, mỗi view có feature2048×7×7. Conv1×1 chiếu sang512kênh, nối các view và flatten thành392visualtokens. Thêm proprio và latent thành394token cho policy encoder; decoder dùng20query để ra chuỗi20×8. Camera identity embedding phân biệt view, còn camera_valid che token của view thiếu. Trong frozen training, loader đọc feature dequantized sẵn nên trường images thực ra chứa feature, không phải RGB; inference ảnh mới vẫn phải chạy backbone.',
'[[J:src/models/mcr_act.py:73]] [[J:src/models/mcr_act.py:129]] [[J:src/models/rh20t_act.py:34]] [[J:src/data/feature_cache.py:393]].',
'“Tám camera là tám ResNet” hoặc “có cache nên inference không tính feature”.','Camera mask khác action padding mask ở đâu?'),
('B06','Temporal ensembling có trong model của các bạn không?','Phân biệt kiến trúc model với executor.',
'ACT gốc có tùy chọn kết hợp các prediction từ những chunk khác nhau nhưng cùng nhắm tới một thời điểm thực thi. Đây là logic ở executor, không tự xuất hiện chỉ vì model dự đoán chuỗi. Probe TCP E5 của nhóm ghi rõ lấy action đầu mỗi tick10Hz, không phải temporal ensemble. Với nhánh joint mới, nhóm chưa có rollout/executor được xác minh để nói đã dùng ensembling. Nếu thêm, cần chốt trọng số, joint limits, xử lý kẹp và đo độ mượt cùng độ phản ứng, chứ không mặc định cứ trung bình là tốt hơn.',
'[[R:epoch5_transfer_probe_14120/pick_place_000938/rollout_report.json:1]]; [ACT eval_bc](https://github.com/tonyzhaozh/act/blob/main/imitate_episodes.py#L225), truy cập17/10/2026.',
'“ACT nào cũng đã bật temporal ensemble”, hoặc nói sai thứ tự trọng số gốc.','Các bạn sẽ so first-action, partial-chunk và ensemble theo metric nào?'),

('C01','Một nghìn demo đạt trên slide được kiểm chứng thế nào?','Đếm đúng dataset, success và quality filtering.',
'Câu đó hiện phải chỉnh lại. Manifest task đích local chấp nhận913episode và từ chối111mục; trong phần từ chối có24mục khôngsuccess và87mục videolỗi hoặc thiếuframe. Split dùng731train,91val,91test. Những số này chứng minh tập được importer chấp nhận ở phiên bản manifest đó, không chứng minh đã có một nghìn demo đều đạt. Cũng không nên lấy913chia1024làm success rate robot vì lỗi video và cách chọn candidate ảnh hưởng mẫu số. Nhóm cần chốt manifest, dữ liệu gốc và tiêu chí chất lượng rồi mới công bố lại số lượng.',
'[[J:data/splits/pick_place_finetune_manifest.json:1]] [[J:data/splits/pick_place_finetune_splits.json:1]]; S17.',
'“1.000đều thành công vì slide ghi thế” hoặc “913/1024làaccuracyACT”.','Trong913accepted, bao nhiêu trajectory độc lập và bao nhiêu chỉ đổi hình ảnh?'),
('C02','Nhãn action của CFG5 mới chính xác là gì?','Semantics measured state so với command.',
'State đầu vào là bảy joint đo được theo radian và độ mở kẹp đo được theo mét. Mỗi hàng action có cùng bảy joint ghi thật nhưng ghép với gripper command; loader lấy các hàng tương lai offset1tick, tối đa20tick. Vì thế phần arm là future measured-state target, chưa phải motor command đã được ghi và xác minh. Đây là lựa chọn có nhãn thật khi TCP thiếu, không phải bịa joint bằng FK. Khi điều khiển phải chuyển prediction thành reference có nội suy và giới hạn phù hợp, đồng thời kiểm trễ của plant.',
'[[J:src/data/cfg5_masked.py:219]] [[J:src/data/act_dataset.py:115]] [[J:scripts/prepare_cfg5_masked_mcr.py:134]].',
'“RH20T ghi trực tiếp mọi lệnh động cơ nên model xuất là gửi thẳng.”','Observationt và targett+1 có ảnh hưởng gì tới gripper command alignment?'),
('C03','Các bạn tránh data leakage bằng cách nào?','Hiểu đơn vị split độc lập và normalization.',
'CFG5 được chia theo group task,user,calibration trước khi tạo action chunk, để các dữ liệu thuộc cùng group không bị rải sang train và test. Normalization chỉ fit train. Với demo mô phỏng, importer gom theo seed hoặc numeric trajectory giống nhau; profilefixed chỉ train trong split hiện có. Tuy nhiên, group split không tự bảo đảm unseen task hay unseen object position. Muốn chứng minh OOD, cần định nghĩa thêm phạm vi vị trí, ánh sáng hoặc vật thể không xuất hiện trong train và không dùng test để chọn checkpoint hay chỉnh ngưỡng.',
'[[J:src/data/splits.py:77]] [[J:src/data/act_dataset.py:10]] [[J:src/data/sim_demos.py:230]].',
'“Chia ngẫu nhiên frame là đủ độc lập” hoặc “cótestsplit nghĩa làđãfew-shot”.','Tại sao hai cửa sổ chồng nhau từ cùng episode không phải hai thử nghiệm độc lập?'),
('C04','Vì sao đổi TCP sang joint, có mất dữ liệu cũ không?','Căn cứ quyết định và kiểm soát phiên bản.',
'Ghi chép ngày11/10 cho thấy có episode thiếu TCP thật, còn kiểm chứng phục hồi TCP bằng FK trên phạm vi rộng chưa đạt, có sai lệch góc khoảng17độ. Vì vậy người dùng chọn7joint và độ mở kẹp từ dữ liệu ghi thật. Sau phục hồi file joint gốc còn đúng4episode thiếu được duyệt loại, giữ raw. Quyết định đó tận dụng được1317episode với mask camera, nhưng làm checkpointTCP và demoTCP không tương thích semantics với policyjoint. Dữ liệu cũ vẫn có giá trị lịch sử, chỉ không được đổi tên các chiều rồi dùng nhưjoint.',
'[[H::3568]] [[H::4276]] [[R:BAN_GIAO_CODEX_CFG5_MCR_2026-10-13.md:76]].',
'“FK đã chuẩn nên tự sinh joint/TCP tùy ý”, hoặc “cùng8Dthìkhôngcầntrainlại”.','Bốn episode loại là vì thiếujoint hay vì policy xử lý không tốt?'),
('C05','Domain randomization của nhóm gồm gì, đã chứng minh tác dụng chưa?','Tách augmentation khỏi robustness.',
'Slide và các profile dữ liệu mô tả biến thiên màu, nền, ánh sáng, vị trí và vật phụ. Manifest có các profilefixed,varied,diverse,rich; ảnh minh họa cho thấy có thay đổi hình ảnh. Tuy nhiên, source generator đúng phiên bản cho toàn bộ tập và range từng tham số chưa được audit đầy đủ trong lượt này. Nhóm chưa có so sánh bật/tắt randomization trên held-out nên chưa khẳng định nó tăng success. Ngoài biến thiên thị giác, cần kiểm ma sát, độ cứng, khối lượng và trễ nếu muốn nói tới sim-to-real cho thao tác tiếp xúc.',
'S17; [[J:data/splits/pick_place_finetune_splits.json:1]]; [Tobin2017](https://arxiv.org/abs/1703.06907), truy cập17/10/2026.',
'“Đổi màu đủ để giải quyết sim-to-real.”','Những tham số vật lý nào đã randomize và phân phối được chọn dựa trên đâu?'),
('C06','Nhánh mới có bao nhiêu dữ liệu, và mọi episode đều expert thành công không?','Chất lượng và license dữ liệu.',
'Log mới xác nhận1317episode được cache, split1053train,132val,132test, tổng574493tick. Đó là số episode hợp lệ theo pipeline joint/mask, không phải số task thành công của robot. Nhánh mới bỏ lọc rating để giữ dữ liệu robot thiếu camera, nên có rủi ro đưa cả quỹ đạo chất lượng thấp vào pretrain. Nhóm cần phân tích chất lượng theo task/rating và so sánh phương án lọc trước khi khẳng định lợi ích. Đồng thời cần audit quyền sử dụng các scene C/NC của RH20T trước pilot thương mại, vì công khai không đồng nghĩa không hạn chế.',
'[[H::4276]] [[J:scripts/prepare_cfg5_masked_mcr.py:35]]; cache log trong00; [RH20Tlicense](https://rh20t.github.io/), truy cập17/10/2026.',
'“1317demođềuđạt” hoặc “datasetpublic nêncommercialfree”.','Mẫu thất bại có thể làm behavior cloning học hành vi sai như thế nào?'),

('D01','Video gắp được có chứng minh ACT đã học không?','Nhận diện scripted oracle và policy.',
'Không tự chứng minh. Controller scripted hiện đọc vị trí vật và offset grasp từ simulator để tạo trajectory, nên có thông tin privileged mà policy không nên được nhận. Báo cáo3/3seed ghi rõact_model_used=false. Video đó chứng minh môi trường, controller và evaluator có thể chạy task trong các điều kiện đã thử. Muốn chứng minhACT, cần nạp checkpoint xác định, chỉ đưa ảnh và trạng thái robot, ghi action từmodel, rồi báoNrollout và failure theo cùng evaluator. Nhóm sẽ gắn nhãn video rõ để không dùng demo engineering làm kết quả học.',
'[[J:src/simulation/panda_demo.py:1]] [[L:outputs/controller_evaluation/summary.json:1]]; S15/17.',
'“Video đẹp nênACTchắcchắnthànhcông.”','Tronginfoenv cóobjectstate, làm sao đảm bảo inference không dùng nó?'),
('D02','Tỷ lệ thành công hiện tại bao nhiêu, vì sao có0/10?','Trình bày kết quả thất bại đúng phạm vi.',
'Có hai kết quả lịch sử rõ: controller scripted3/3seed vàACTTCPcheckpointE5transfer0/10episodevalidation. ProbeE5 còn có offlinepositiondistance khoảng66,65mm và lỗi kẹp khoảng29,17mm, cho thấy chưa đáp ứng task chốt nhỏ trong điều kiện đó. Nhóm không dùng kết quả ấy để kết luận nhánhjointMCR mới cũng thất bại, nhưng cũng không được giấu nó. Hiện chưa cóN/Ncủa nhánhmới. Cần làm rolloutđúngrepresentation và báo cả error, success, timeout cùngvideo; chưa có ablation để quy nguyên nhân0/10chỉ cho backbone.',
'[[R:epoch5_transfer_probe_14120/report.json:1]] [[L:outputs/controller_evaluation/summary.json:1]].',
'“0/10không quan trọng” hoặc “chỉdoResNetnênđổiMCRlàxong”.','Thí nghiệm nào sẽ phân biệt lỗi dữ liệu, output semantics, vision và controller?'),
('D03','Các bạn định nghĩa đặt đúng thế nào?','Chất lượng evaluator và tránh false success.',
'Task dùng ba chốtØ6mm,dài35mm vào lỗØ7mm,sâu12mm. Đặt đúng không chỉ là gần tâm. Evaluator kiểm bao hình học nằm trong lỗ, độ nhô23±0,5mm, đáy gần mặtđỡ, không xuyên quá mức, nghiêng trong3độ, vận tốc nhỏ, đã nhả và có lực đỡ đáy. Điều kiện phải ổn định ít nhất0,5giây, đồng thời có lịch sử grasp hai ngón và lift. Task chỉ thành công khi cả ba chốt đạt. Đó là tiêu chí mô phỏng đã cài; qualitycheck ngoài đời vẫn cần phép đo độc lập.',
'[[J:configs/mujoco/panda_three_pegs.json:1]] [[J:src/simulation/panda_evaluator.py:65]].',
'“Nhìn vật trong lỗ là đạt”, hoặc lấy tolerance±0,5mm làmMAEpolicy.', 'Nếu chốt nằm lơ lửng hoặc còn được robot giữ thì evaluator có báo thành công không?'),
('D04','Sim-to-real gap của các bạn nằm ở đâu?','Hiểu giới hạn simulator.',
'Có ít nhất bốn khoảng cách: ảnh và ánh sáng, động học/tool calibration, tiếp xúc vật lý như ma sát/compliance, và thời gian của camera/inference/controller. Mô phỏng cóPanda vàcontactmodel, nhưng chưa là digitaltwin đã hiệu chuẩn của cellDENSO. MCRpretrain vàrandomization là lựa chọn để thử giảm một phần gap, không bảo đảm chuyển thẳng. Nhóm cần chốt robotthật, đo calibration/tracking vàlatency, thu ít realdemo phùhợp rồi đánhgiá an toàn theo gate. Trước đó cần learnedrolloutjoint đạt trong môphỏng; hiện mắt xích ấy còn thiếu xác minh.',
'[[J:src/simulation/panda_env.py:12]] [[J:src/models/mcr_act.py:25]];06 mục4.',
'“MuJoColàvật lýthật nênkhôngcòngap.”','Các bạn đo tham số ma sát và độ cứng của linh kiện thật bằng cách nào?'),
('D05','Nếu robot xưởng là6trục hoặc7trục khácPanda thì làm thế nào?','Khả thi chuyển embodiment.',
'Nhóm chưa biết model robotxưởng nên trình bày hai trường hợp. Robot6trục nếu xuấtjoint thường cầnstate/action6joint cộng gripper, cùng dữ liệu,head,stats vàdriver mới; không bỏ một gócPanda là chạy. Robot7trục khácPanda có thể giữ số chiều nhưng jointzero,sign,linklength,limits vàtool vẫn khác, nên cũng cần retarget hoặc data tương ứng và thửnghiệm. Ngay cảPanda thật cùngloại còn camera,dynamics vàsafetygap. Nhóm tái dùng pipeline và có thể thử visualweights, chưa cam kết táidùng nguyênpolicyjoint.',
'[[J:src/simulation/panda_controller.py:34]] [[J:src/models/rh20t_act.py:71]];06 mục3.',
'“Cùng7trụclàtươngthích” hoặc “6trụcchỉxóamộtoutput”.','TCP representation có giúp chuyển robot dễ hơn không, và đánh đổi gì?'),
('D06','Model chạy tần số bao nhiêu, có điều khiển trực tiếp động cơ không?','Hiểu các tầng thời gian và real-time.',
'Lưới dữ liệu và target của nhóm là10Hz,chunk20bước bằng2giây. Môi trường mô phỏng chạyphysicsdt1ms, controller cậpnhật reference trong từngsubstep và evaluator100Hz. Những tần số đó khác nhau. ProbeTCPcũ hỏi model mỗi tick10Hz; nhánhjoint mới chưa cólatency hay queryfrequency thực tế được đo. Nếu dùngPandaFCIthật, API có vòngreal-time1kHz nhưng cần bộnội suy/tracking phùhợp, không đưa một mạngvision10Hz vào vòngmotor rồi mặcđịnh đạtdeadline. Robotxưởng khác có giao diện và ràngbuộc riêng phải kiểm.',
'[[J:src/simulation/panda_env.py:23]] [[J:src/simulation/panda_controller.py:74]]; [FCI](https://frankarobotics.github.io/docs/overview.html), truy cập17/10/2026.',
'“Inferenceđang1kHzvìdtMuJoCo1ms” hoặc “0,325schecklàlatencyonline”.','Các bạn sẽ đo latency capture-to-command và deadline miss như thế nào?'),

('E01','Làm sao đảm bảo an toàn khi đưaAI vào nhà máy?','Trách nhiệm safety và ranh giới prototype.',
'Hiện nhóm chưa có xác nhận an toàn của một cell thật. Các giới hạnworkspace vàrate trongsim chỉ là lớp kỹthuật, không thay thế riskassessment và hệthốngsafety của robot/cell. Kếhoạchpilot cần kỹsưxưởng chốtguard,interlock,E-stop,quytrìnhenable/restart vàxửlýsự cố theo thiếtbị thực. Policy chỉ sinhreference trongphạmvi đượccho phép, không nắm chức năngsafety. Nhóm sẽđi qua cácgate môphỏng,bench vàpilot cógiámsát trước nghiệpthu. Chưa đủ thôngsốrobot vàcell nên chưa đưa racamkết antoàn chungchung.',
'[[J:src/simulation/panda_controller.py:16]];06 mục5; [OSHA risk assessment](https://www.osha.gov/otm/section-4-safety-hazards/chapter-4), truy cập17/10/2026.',
'“Cobottựđộngantoàn” hoặc “AIđãhọcva chạmnênkhôngcầnguard”.','Khi người vào cell hoặc camera/GPU hỏng, ai ra lệnh dừng?'),
('E02','Không dự đoán lực thì kẹp linh kiện dễ vỡ thế nào?','Thành thật về contact-rich manipulation.',
'Đầu ra hiện chỉ joint vàwidth nên nhóm chưa chứng minh điều khiển lực trên vật dễvỡ. Width nhỏ không đồng nghĩa force nhỏ vì còn cơcấu,độcứng,tracking vàtiếp xúc. Config cóforcelimit nhưng đó là ràngbuộccontrollertrongsim, không làfeedbackforcepolicy hoặc testvậtliệu. Trướcpilot cần lựa chọn gripper/tool, đo lực hoặc contact, chốtngưỡng chấtlượng vàcơchếdừngkhi kẹt. Nếu task thật đòi lực tinhvi mà hệthống hiệnchưađápứng, nhóm sẽthu hẹp mục tiêu hoặc bổ sungfeedback, không hứa thayngười ngay.',
'[[J:src/models/mcr_act.py:137]] [[J:configs/mujoco/panda_three_pegs.json:1]]; S13/18/36.',
'“Độmởkẹpchínhlàlực” hoặc “20Nchắcantoànvớimọilinhkiện”.','Lực và tỷ lệ hỏng linh kiện sẽ được đo bằng cảm biến/phép thử nào?'),
('E03','Hệ thống tích hợp vàoPLC/MES hiện có ra sao?','Khả năng vận hành ngoài demo.',
'Hiện source có môi trường vàmetricmôphỏng, chưa cóbáocáo integrationPLC/MESproduction. Phần cầnthiết kế làcellstate machine nhậnrecipe/partID, kiểmReady, phátBusy, trảDone hoặcFault cùngqualityresult, cótimeout vàxácnhận từthiếtbị liênquan. Model/checkpoint vàcalibration phải đượcversion theo recipe. KhiAI khôngđủobservation hoặcdriver lỗi, cellcần đườngdừng vàfallback doxưởng phêduyệt. Đây làđềxuấttriểnkhai, không phải tínhnăngđãlắp. Nhóm cần lấyinterfacelist từkỹsưDENSO rồi mới camkếtgiao thức vàchi phí.',
'[[J:src/simulation/panda_evaluator.py:65]] [[J:src/simulation/panda_env.py:126]]; S36;06 mục5.',
'“CóJSONlognghĩalàđãđồngbộMESthờigianthực.”','Cell biết một linh kiện đã đặt đúng và được dây chuyền nhận bằng tín hiệu nào?'),
('E04','Robot gắp hụt, làm rơi hoặc đặt kẹt thì xử lý thế nào?','Failure recovery và giới hạn hành vi.',
'Trongsim,evaluator cógrasp,lift,drop vàfailurereason để quan sát lỗi, nhưng đó chưa làrecoverypolicy đãđượctrain. Đềxuấtpilot làxácnhậngrasp/placement bằngtínhiệu phùhợp, dừngcókiểmsoátkhi lỗi, phânloạipartreject hoặccho phép retrygiớihạn khi đãđánhgiá antoàn, rồi gọingười nếu lặplại. Không đểmodel tựthửlại vôhạn hoặc tiếp tục insert khi nghi kẹt. Nhóm cần logloạilỗi,tần suất,thờigiancanthiệp vàtỷlệkhôiphục đểtính cảKPI vàchi phívậnhành.',
'[[J:src/simulation/panda_evaluator.py:88]] [[J:src/simulation/panda_env.py:147]];06 mục5.',
'“AIhọcđượcnênsẽtựsửamọilỗi.”','Retry bao nhiêu lần, điều kiện nào buộc người xử lý và robot ở trạng thái nào?'),
('E05','Ai kiểm tra chất lượng và bảo trì sau triển khai?','Lifecycle cost và trách nhiệm vận hành.',
'Nhóm chưa cóquytrìnhvậnhànhproduction đượcxưởngphêduyệt. Evaluatormôphỏng dùngvịtrí/contact thậttrongsim, cònngoàiđời phải chọnphépđođộc lập nhưvisioninspection,gauge hoặc sensorphùhợp với dungsai. Phầnbảotrì cần kiểmgripper,camera/calibration,vệsinh vàregressiontest saukhi thaythiếtbị. Model phải cóversion,rollback vàlogảnh/action/quality cầnthiết theo quyềndữliệu. Thờigian vàchi phícho cácviệc này phải đưa vàoOPEX; hiện chưađo nên nhóm khôngnói bảo trìthấp hay24/7đãđượcchứngminh.',
'[[J:src/simulation/panda_evaluator.py:65]]; S35/36;06 mục5.',
'“Đầu tư một lần, hầu như không có bảo trì.”','Sau khi thay camera hoặc ngón kẹp, điều kiện nào cho phép chạy lại?'),
('E06','DENSO có cần cho các bạn robot thật ngay không?','Biết đặt gate nghiệm thu và yêu cầu nguồn lực.',
'Nhóm nên chốtthôngsố vàinterface sớm để khôngtrain saiembodiment, nhưngchưa cần đưa policy chưađánhgiá vào cellđangchạy. Trướctiên cầnnốijointadapter,kiểmtracking vàđolearnedrollout trongsim, rồi dùngbench/pilot cógiámsát với tiêuchí đãthốngnhất. Nguồncầnxưởng cungcấp làmodelrobot,gripper/tool,bảnvẽlinhkiện,calibrationkhảthi,takt vàqualitybaseline. FAQ cũng ưu tiên môphỏng rồi đánhgiá trước khi xácnhận trênrobot thật. Nhóm chưa cósuccess/safetygate bằngsố củaBTC nên sẽxinchốt với mentor, không tựnhận đãđủđiềukiện.',
'[[J:src/simulation/panda_controller.py:16]]; [FAQH1/Robotics](https://densohackathon.vn/qa), truy cập17/10/2026.',
'“Córobotthậtthìmaiđưamodelxuốngchạyngay.”','Điều kiện tối thiểu để chuyển từsim sangbench là gì?'),
]
